import static org.junit.jupiter.api.Assertions.assertEquals;

import com.wolinski.shop.money.Money;
import java.time.Clock;
import java.time.Instant;
import java.time.ZoneOffset;
import org.junit.jupiter.api.Test;

class OrderServiceTest {

    private static final Instant NOW = Instant.parse("2026-10-31T12:00:00Z");

    private final OrderRepository orders = new OrderRepository();
    private final OrderService service =
            new OrderService(orders, Clock.fixed(NOW, ZoneOffset.UTC));

    @Test
    void expireStaleCancelsOnlyPlacedOrdersOlderThan30Days() {
        String old = place(NOW.minus(31, java.time.temporal.ChronoUnit.DAYS));
        String justInside = place(NOW.minus(30, java.time.temporal.ChronoUnit.DAYS).plusSeconds(1));
        String exactlyAtCutoff = place(NOW.minus(30, java.time.temporal.ChronoUnit.DAYS));
        String recent = place(NOW.minusSeconds(60));
        String oldButConfirmed = place(NOW.minus(90, java.time.temporal.ChronoUnit.DAYS));
        service.confirm(oldButConfirmed);
        String oldAndCancelled = place(NOW.minus(90, java.time.temporal.ChronoUnit.DAYS));
        service.cancel(oldAndCancelled);

        int cancelled = service.expireStale();

        assertEquals(1, cancelled);
        assertEquals("CANCELLED", service.summary(old).status());
        assertEquals("PLACED", service.summary(justInside).status());
        assertEquals("PLACED", service.summary(exactlyAtCutoff).status());
        assertEquals("PLACED", service.summary(recent).status());
        assertEquals("CONFIRMED", service.summary(oldButConfirmed).status());
        assertEquals("CANCELLED", service.summary(oldAndCancelled).status());
    }

    @Test
    void expireStaleReturnsZeroWhenNothingIsStale() {
        place(NOW.minusSeconds(60));

        assertEquals(0, service.expireStale());
    }

    @Test
    void expireStaleIsIdempotent() {
        place(NOW.minus(45, java.time.temporal.ChronoUnit.DAYS));

        assertEquals(1, service.expireStale());
        assertEquals(0, service.expireStale());
    }

    private String place(Instant placedAt) {
        return service.place("c-1", Money.pln(1000), placedAt);
    }
}
}

